fn count_s_and_distinct(s: Str) -> (Int, Int) {
    let mut s_count = 0
    let mut seen = Vec<Bool>()
    for c in chars(s) {
        if c == "s" {
            s_count = s_count + 1
        }
        let mut is_new = True
        for sc in seen {
            if sc == (c == sc) {
                is_new = False
                break
            }
        }
        if is_new {
            seen = push(seen, c == c)
        }
    }
    (s_count, len(seen))
}

